content.problemStatement:
You are given a function,
int FindMaxProduct(int** arr, int n);
int FindMaxProduct(int** arr, int n);
static int FindMaxProduct(int arr[][]);
static int FindMaxProduct(int[,] arr);
def FindMaxProduct(arr)
The function takes a two-dimensional array having equal number of rows and columns (i.e. a
square matrix) and its dimension, 'n', as input. Implement the function such that it returns the
maximum product that can be formed from four adjacent numbers. Numbers can be adjacent to
each other in either of the given directions: up, down, left, right, diagonal or anti-diagonal. Ensure
that four adjacent numbers are chosen in such a way that the direction does not change while
choosing the numbers. Assume 'n' >= 4.

code.C:
#include <stdio.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long mat[105][105];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            scanf("%lld", &mat[i][j]);
    long long max_p = -2e18;
    int dr[] = {0, 1, 1, 1};
    int dc[] = {1, 0, 1, -1};
    for (int r = 0; r < n; r++) {
        for (int c = 0; c < n; c++) {
            for (int d = 0; d < 4; d++) {
                int r3 = r + 3 * dr[d], c3 = c + 3 * dc[d];
                if (r3 >= 0 && r3 < n && c3 >= 0 && c3 < n) {
                    long long p = mat[r][c] * mat[r+dr[d]][c+dc[d]] * mat[r+2*dr[d]][c+2*dc[d]] * mat[r+3*dr[d]][c+3*dc[d]];
                    if (p > max_p) max_p = p;
                }
            }
        }
    }
    printf("%lld\n", max_p);
    return 0;
}

