        const dr = [0, 1, 1, 1];
        const dc = [1, 0, 1, -1];
        for (let r = 0; r < n; r++) {
            for (let c = 0; c < n; c++) {
                for (let d = 0; d < 4; d++) {
                    const r3 = r + 3 * dr[d], c3 = c + 3 * dc[d];
                    if (r3 >= 0 && r3 < n && c3 >= 0 && c3 < n) {
                        const p = mat[r][c] * mat[r+dr[d]][c+dc[d]] * mat[r+2*dr[d]][c+2*dc[d]] * mat[r+3*dr[d]][c+3*dc[d]];
                        if (p > maxP) maxP = p;
                    }
                }
            }
        }
        console.log(maxP);
    }
}
